## IO correctness ----
test_that("`set_fixed()` updates fixed-effect parameters in the model tape", {
  clear()

  selectivity <- methods::new(LogisticSelectivity)
  selectivity$inflection_point[1]$value <- 10.0
  selectivity$inflection_point[1]$estimation_type$set("fixed_effects")
  selectivity$slope[1]$value <- 0.2
  selectivity$slope[1]$estimation_type$set("fixed_effects")

  CreateTMBModel()
  updated_fixed <- get_fixed() + c(0.5, -0.1)
  set_fixed(updated_fixed)

  #' @description Test that `set_fixed()` updates values returned by `get_fixed()`.
  expect_equal(get_fixed(), updated_fixed)

  clear()
})

test_that("`set_random()` updates random-effects parameters in the model tape", {
  clear()

  selectivity <- methods::new(DoubleLogisticSelectivity)
  selectivity$inflection_point_asc[1]$value <- 2.0
  selectivity$inflection_point_asc[1]$estimation_type$set("random_effects")
  selectivity$inflection_point_desc[1]$value <- 4.0
  selectivity$inflection_point_desc[1]$estimation_type$set("random_effects")
  selectivity$slope_asc[1]$value <- 0.4
  selectivity$slope_asc[1]$estimation_type$set("random_effects")
  selectivity$slope_desc[1]$value <- 0.2
  selectivity$slope_desc[1]$estimation_type$set("random_effects")

  CreateTMBModel()
  updated_random <- get_random() + c(0.3, -0.2, 0.1, -0.05)
  set_random(updated_random)

  #' @description Test that `set_random()` updates values returned by `get_random()`.
  expect_equal(get_random(), updated_random)

  clear()
})

test_that("logging helpers record info, warning, and error messages", {
  clear()
  set_log_throw_on_error(FALSE)

  log_info("unit-test info message")
  log_warning("unit-test warning message")
  expect_no_error(log_error("unit-test error message"))

  log_all <- get_log()
  log_warnings <- get_log_warnings()
  log_errors <- get_log_errors()

  #' @description Test that `get_log()` includes info and warning entries added through logging helpers.
  expect_match(log_all, "unit-test info message", fixed = TRUE)
  expect_match(log_all, "unit-test warning message", fixed = TRUE)
  #' @description Test that `get_log_warnings()` includes warning entries added through `log_warning()`.
  expect_match(log_warnings, "unit-test warning message", fixed = TRUE)
  #' @description Test that `get_log_errors()` includes error entries added through `log_error()`.
  expect_match(log_errors, "unit-test error message", fixed = TRUE)

  clear()
})

